/**
 * Remove malformed image variants (e.g. hero-blue-ar-1024w-1024w-480w.webp)
 * that were generated by a bug - only keeps correctly named files.
 */
import fs from 'fs';
import path from 'path';

const PUBLIC_DIR = path.join(process.cwd(), 'public');

function isMalformed(filename) {
  // Has multiple -XXXw segments (e.g. hero-blue-ar-1024w-768w-480w.webp)
  const matches = filename.match(/-\d+w/g);
  return matches && matches.length > 1;
}

function main() {
  if (!fs.existsSync(PUBLIC_DIR)) {
    console.log('No public dir');
    return;
  }
  const files = fs.readdirSync(PUBLIC_DIR);
  let deleted = 0;
  for (const file of files) {
    if (!fs.statSync(path.join(PUBLIC_DIR, file)).isFile()) continue;
    if (isMalformed(file)) {
      const p = path.join(PUBLIC_DIR, file);
      fs.unlinkSync(p);
      console.log('Deleted:', file);
      deleted++;
    }
  }
  console.log('Total deleted:', deleted);
}

main();
